class Solution {
  public int possibleStringCount(String word, int k) {
    final int MOD = 1_000_000_007;
    List<Integer> runs = new ArrayList<>();
    for (int i = 0, n = word.length(); i < n; ) {
      int j = i;
      while (j < n && word.charAt(j) == word.charAt(i)) j++;
      runs.add(j - i);
      i = j;
    }
    long total = 1;
    for (int r : runs) total = total * r % MOD;
    if (runs.size() >= k) return (int) total;
    long[] dp = new long[k];
    dp[0] = 1;
    long[] pre = new long[k + 1];
    for (int r : runs) {
      pre[0] = 0;
      for (int j = 0; j < k; j++) pre[j + 1] = (pre[j] + dp[j]) % MOD;
      long[] nd = new long[k];
      for (int j = 1; j < k; j++) {
        int lo = Math.max(0, j - r);
        nd[j] = (pre[j] - pre[lo] + MOD) % MOD;
      }
      dp = nd;
    }
    long bad = 0;
    for (long v : dp) bad += v;
    return (int) (((total - bad) % MOD + MOD) % MOD);
  }
}
